int copy_auth_to_skb(struct xfrm_algo_auth *auth, struct sk_buff *skb) {
    struct nlattr *nla;

    nla = skb_reserve(skb, nla_attr_size(XFRMA_ALG_AUTH));
    if (!nla)
        return -EMSGSIZE;

    nla->nla_type = XFRMA_ALG_AUTH;
    nla->nla_len = nla_total_size(strlen(auth->alg_name) + 1) +
                   nla_total_size(auth->alg_key_len);

    nla_put(skb, XFRMA_ALG_AUTH_NAME, strlen(auth->alg_name) + 1, auth->alg_name);
    nla_put(skb, XFRMA_ALG_AUTH_KEY, auth->alg_key_len, auth->alg_key);

    return 0;
}

