int copy_auth_to_skb(struct xfrm_algo_auth *auth, struct sk_buff *skb)
{
    struct nlattr *nla;

    nla = skb_reserve(skb, 0, sizeof(*nla) + auth->alg_key_len, GFP_ATOMIC);
    if (!nla)
        return -EMSGSIZE;

    nla->nla_type = XFRMA_ALG_AUTH;
    nla->nla_len = sizeof(*nla) + auth->alg_key_len;
    memcpy(nla + 1, auth, auth->alg_key_len + sizeof(*auth) - auth->alg_key);

    return 0;
}
